#include <system_error>
#include <functional>
#include <sstream>
#include <cassert>
#include <iostream>

int main() {
    std::error_condition error = std::make_error_condition(std::errc::invalid_argument);
    assert(error);
    assert(error.value() != 0);
    assert(!error.message().empty());
    assert(error.category() == std::generic_category());
    std::error_condition copy;
    copy.assign(error.value(), error.category());
    assert(copy == error);
    assert(std::hash<std::error_condition>{}(copy) ==
        std::hash<std::error_condition>{}(error));
    copy.clear();
    assert(!copy);
    copy = std::make_error_condition(std::errc::invalid_argument);
    assert(copy == error);

    std::cout << "Checks passed\n";
}
